  function ltrScore(f, mode) {
    var m = (mode === 'jra' && LTR_MODEL.jra) ? LTR_MODEL.jra
          : (mode === 'narR' && LTR_MODEL.narR) ? LTR_MODEL.narR : LTR_MODEL.nar;
    if (mode === 'narR' && !LTR_MODEL.narR) return null;   // 補助が無ければC12を使わない
    var F = m.feats, trees = m.trees;
    var s = 0;
    for (var i = 0; i < trees.length; i++) {
      var n = trees[i];
      while (n.length > 1) {
        var v = f[F[n[0]]];
        var miss = (v === null || v === undefined || v !== v);
        var goLeft;
        if (miss) goLeft = (n[2] === 1);
        else if (n[1] instanceof Array) goLeft = n[1].indexOf(Math.round(+v)) >= 0;
        else goLeft = (+v <= n[1]);
        n = goLeft ? n[3] : n[4];
      }
      s += n[0];
    }
    return s;
  }
  var api = { LTR_MODEL: LTR_MODEL, ltrScore: ltrScore };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else { root.LTR_MODEL = LTR_MODEL; root.ltrScore = ltrScore; }
